"""Expected velocity declines, computed from the generated files (no services needed)."""
import json
from collections import Counter, defaultdict, deque
from datetime import datetime

WINDOW_S, LIMIT = 300, 10          # rule: stored count + 1 > 10 within 5 minutes

with open("labels.jsonl") as f:
    labels = {r["transaction_id"]: r["label"] for r in map(json.loads, f)}

events = []
with open("payments.jsonl") as f:
    for p in map(json.loads, f):
        t = datetime.fromisoformat(p["event_time"]).timestamp()
        events.append((t, p["card_token"], labels[p["transaction_id"]]))
events.sort()

recent, expected = defaultdict(deque), Counter()
for t, card, label in events:
    q = recent[card]
    while q and q[0] <= t - WINDOW_S:      # drop payments older than 5 minutes
        q.popleft()
    if len(q) + 1 > LIMIT:                 # declined payments still count, as in the real system
        expected[label] += 1
    q.append(t)

print("expected velocity declines:", dict(expected))
